/**
 * Helpers for translating between browser scrollLeft and a logical offset that
 * always grows from the first item toward later items in both LTR and RTL.
 *
 * Modern Chromium/WebKit/Firefox expose RTL scrollLeft as 0 at the start
 * (inline-start) and increasingly negative values toward the end. Positive
 * values during rubber-band overscroll are clamped to logical 0.
 *
 * Pass a precomputed `isRtl` flag. The carousel hook caches direction from the
 * effect / snap path so native scroll frames do not call getComputedStyle.
 */
const isElementRtl = (element) => getComputedStyle(element).direction === 'rtl';
const toUnsignedZero = (value) => (Object.is(value, -0) ? 0 : value);
const getLogicalScrollLeft = (element, isRtl) => {
    const { scrollLeft } = element;
    if (!isRtl) {
        return toUnsignedZero(scrollLeft);
    }
    // Clamp positive overscroll (e.g. iOS rubber-band at start) to logical 0.
    return Math.max(0, toUnsignedZero(-scrollLeft));
};
const setLogicalScrollLeft = (element, logicalScrollLeft, isRtl) => {
    const nextLogical = Math.max(0, toUnsignedZero(logicalScrollLeft));
    if (!isRtl) {
        // eslint-disable-next-line no-param-reassign -- DOM scrollLeft write
        element.scrollLeft = nextLogical;
        return;
    }
    // eslint-disable-next-line no-param-reassign -- DOM scrollLeft write
    element.scrollLeft = nextLogical === 0 ? 0 : -nextLogical;
};

export { getLogicalScrollLeft, isElementRtl, setLogicalScrollLeft };
